def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return out
    bottom = max(r for r, c, v in points)

    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    if r + 1 == bottom:
                        sr, sc, dr, step = r + 1, nc, 1, dc
                    else:
                        sr, sc, dr, step = r, c, -1, -dc
                    rr, cc = sr + dr, sc + step
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == bg:
                            out[rr][cc] = color
                        rr += dr
                        cc += step
    return out
